   136	uint8_t uart_hal_get_symb_len(uart_hal_context_t *hal)
   137	{
   138	    uint8_t symbol_len = 1; // number of bits per symbol including start
   139	    uart_parity_t parity_mode;
   140	    uart_stop_bits_t stop_bit;
   141	    uart_word_length_t data_bit;
   142	    uart_ll_get_data_bit_num(hal->dev, &data_bit);
   143	    uart_ll_get_stop_bits(hal->dev, &stop_bit);
   144	    uart_ll_get_parity(hal->dev, &parity_mode);
   145	    symbol_len += (data_bit < UART_DATA_BITS_MAX) ? (uint8_t)data_bit + 5 : 8;
   146	    symbol_len += (stop_bit > UART_STOP_BITS_1) ? 2 : 1;
   147	    symbol_len += (parity_mode > UART_PARITY_DISABLE) ? 1 : 0;
   148	    return symbol_len;
   149	}
