   237	/**
   238	 * @brief Check if UART is enabled or disabled.
   239	 *
   240	 * @param uart_num UART port number, the max port number is (UART_NUM_MAX -1).
   241	 *
   242	 * @return true: enabled; false: disabled
   243	 */
   244	FORCE_INLINE_ATTR bool uart_ll_is_enabled(uint32_t uart_num)
   245	{
   246	    bool uart_rst_en = true;
   247	    bool uart_apb_en = false;
   248	    bool uart_sys_en = false;
   249	    switch (uart_num) {
   250	    case 0:
   251	        uart_rst_en = HP_SYS_CLKRST.hp_rst_en1.reg_rst_en_uart0_apb;
   252	        uart_apb_en = HP_SYS_CLKRST.soc_clk_ctrl2.reg_uart0_apb_clk_en;
   253	        uart_sys_en = HP_SYS_CLKRST.soc_clk_ctrl1.reg_uart0_sys_clk_en;
   254	        break;
   255	    case 1:
   256	        uart_rst_en = HP_SYS_CLKRST.hp_rst_en1.reg_rst_en_uart1_apb;
   257	        uart_apb_en = HP_SYS_CLKRST.soc_clk_ctrl2.reg_uart1_apb_clk_en;
   258	        uart_sys_en = HP_SYS_CLKRST.soc_clk_ctrl1.reg_uart1_sys_clk_en;
   259	        break;
   260	    case 2:
   261	        uart_rst_en = HP_SYS_CLKRST.hp_rst_en1.reg_rst_en_uart2_apb;
   262	        uart_apb_en = HP_SYS_CLKRST.soc_clk_ctrl2.reg_uart2_apb_clk_en;
   263	        uart_sys_en = HP_SYS_CLKRST.soc_clk_ctrl1.reg_uart2_sys_clk_en;
   264	        break;
   265	    case 3:
   266	        uart_rst_en = HP_SYS_CLKRST.hp_rst_en1.reg_rst_en_uart3_apb;
   267	        uart_apb_en = HP_SYS_CLKRST.soc_clk_ctrl2.reg_uart3_apb_clk_en;
   268	        uart_sys_en = HP_SYS_CLKRST.soc_clk_ctrl1.reg_uart3_sys_clk_en;
   269	        break;
   270	    case 4:
   271	        uart_rst_en = HP_SYS_CLKRST.hp_rst_en1.reg_rst_en_uart4_apb;
   272	        uart_apb_en = HP_SYS_CLKRST.soc_clk_ctrl2.reg_uart4_apb_clk_en;
   273	        uart_sys_en = HP_SYS_CLKRST.soc_clk_ctrl1.reg_uart4_sys_clk_en;
   274	        break;
   275	    case 5:
   276	        uart_rst_en = LPPERI.reset_en.rst_en_lp_uart;
   277	        uart_apb_en = LPPERI.clk_en.ck_en_lp_uart;
   278	        uart_sys_en = true;
   279	        break;
   280	    default:
   281	        // Unknown uart port number
   282	        HAL_ASSERT(false);
   283	        break;
   284	    }
   285	    return (!uart_rst_en && uart_apb_en && uart_sys_en);
   286	}
